def isParentSum(root):
    # Base case: empty node satisfies property
    if not root:
        return True
    # Base case: leaf node satisfies property
    if not root.left and not root.right:
        return True
    # Sum of children
    child_sum = 0
    if root.left:
        child_sum += root.left.val
    if root.right:
        child_sum += root.right.val
    # Check current node and recursively check children
    return root.val == child_sum and isParentSum(root.left) and isParentSum(root.right)

def changeTree(root):
    # Base case: if root is None, return
    if not root:
        return
    # Base case: if it is a leaf node, return
    if not root.left and not root.right:
        return
    # Calculate sum of children
    child_sum = 0
    if root.left:
        child_sum += root.left.val
    if root.right:
        child_sum += root.right.val
    # If parent's value is greater than sum of children
    if root.val > child_sum:
        if root.left:
            root.left.val = root.val
        if root.right:
            root.right.val = root.val
    # Recurse on left and right subtrees
    changeTree(root.left)
    changeTree(root.right)
    # Post-order update of parent value
    tot_sum = 0
    if root.left:
        tot_sum += root.left.val
    if root.right:
        tot_sum += root.right.val
    # Update parent value
    root.val = tot_sum

def distanceK(root, target, k):
    from collections import defaultdict
    # Adjacency list representation of the tree as a graph
    graph = defaultdict(list)
    # DFS helper to build graph edges
    def build_graph(node, parent):
        if not node:
            return
        if parent:
            graph[node.val].append(parent.val)
            graph[parent.val].append(node.val)
        build_graph(node.left, node)
        build_graph(node.right, node)
    # Build graph starting from root
    build_graph(root, None)
    # BFS initialization
    queue = [target.val]
    visited = {target.val}
    curr_dist = 0
    # BFS up to distance k
    while queue:
        if curr_dist == k:
            return queue
        next_queue = []
        for node_val in queue:
            for neighbor in graph[node_val]:
                if neighbor not in visited:
                    visited.add(neighbor)
                    next_queue.append(neighbor)
        queue = next_queue
        curr_dist += 1
    # Return empty list if target distance cannot be reached
    return []

def countNodes(root):
    # Base case: if root is None, return 0
    if not root:
        return 0
    # Count 1 for the root, plus recursive count of left and right subtrees
    return 1 + countNodes(root.left) + countNodes(root.right)

def countNodes(root):
    # If root is None, return 0
    if not root:
        return 0
    # Helper to calculate left height
    def get_left_height(node):
        h = 0
        while node:
            h += 1
            node = node.left
        return h
    # Helper to calculate right height
    def get_right_height(node):
        h = 0
        while node:
            h += 1
            node = node.right
        return h
    # Calculate heights
    lh = get_left_height(root)
    rh = get_right_height(root)
    # If left height equals right height, it is a perfect binary tree
    if lh == rh:
        return (1 << lh) - 1
    # Otherwise, recursively count nodes in left and right subtrees
    return 1 + countNodes(root.left) + countNodes(root.right)

def serialize(root):
    # Helper to calculate height of tree
    def get_height(node):
        if not node: return 0
        return 1 + max(get_height(node.left), get_height(node.right))
    h = get_height(root)
    # Total slots needed for a full binary tree
    total_size = (1 << h) - 1
    arr = ["#"] * total_size
    # Helper to place nodes in array
    def fill(node, i):
        if not node: return
        arr[i] = str(node.val)
        fill(node.left, 2 * i + 1)
        fill(node.right, 2 * i + 2)
    fill(root, 0)
    return ",".join(arr)

def deserialize(data):
    if not data:
        return None
    arr = data.split(",")
    nodes = [None if val == "#" else TreeNode(int(val)) for val in arr]
    for i in range(len(nodes)):
        if nodes[i]:
            left_idx = 2 * i + 1
            right_idx = 2 * i + 2
            if left_idx < len(nodes):
                nodes[i].left = nodes[left_idx]
            if right_idx < len(nodes):
                nodes[i].right = nodes[right_idx]
    return nodes[0] if nodes else None

def insertIntoBST(root, val):
    # If root is None, return new node
    if not root:
        return TreeNode(val)
    # Recurse on left or right subtree
    if val < root.val:
        root.left = insertIntoBST(root.left, val)
    else:
        root.right = insertIntoBST(root.right, val)
    # Return root
    return root

def insertIntoBST(root, val):
    # If root is None, return new node
    if not root:
        return TreeNode(val)
    # Pointer to traverse the BST
    curr = root
    # Loop to find the insertion point
    while True:
        # If value is smaller than current node
        if val < curr.val:
            # If left child exists, move left
            if curr.left:
                curr = curr.left
            # If left child is None, insert here
            else:
                curr.left = TreeNode(val)
                break
        # If value is larger than current node
        else:
            # If right child exists, move right
            if curr.right:
                curr = curr.right
            # If right child is None, insert here
            else:
                curr.right = TreeNode(val)
                break
    # Return the root of BST
    return root
